select ?, typeof(?), ?3, :a, @b, $c, $x;
select ?1, ?1 || ?2, ?2 + 1, typeof(?3), length(?4), quote(?5), hex(?6);
select ?10, ?2, ?7;
select :n1, :n1, :n2, @n1, $n1;
select $x, $y::z, $a(b), :é;
create table t(a, b text, c real, d blob, e integer, f numeric);
insert into t values(?, ?, ?, ?, ?, ?);
insert into t values(?6, ?5, ?4, ?3, ?2, ?1);
insert into t(a, b, c) values(:a, :b, :c), (:c, :b, :a);
select rowid, typeof(a), quote(a), typeof(b), quote(b), typeof(c), quote(c), typeof(d), quote(d), typeof(e), quote(e), typeof(f), quote(f) from t order by rowid;
select * from t where a = ? or b = ?;
select count(*) from t where c > ?;
select ? in (1, 2, 1007), ? between 0 and 2, coalesce(?, ?, 'x');
select case ? when 1007 then 'int' else 'other' end, ? is null, ?3 is null, ?5 is null;
select ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?;
select ?999;
select ?1000;
select ?0;
select ?32767;
update t set e = ? where rowid = ?;
delete from t where rowid = ?;
select substr(?2, 1, 1), upper(?2), json_quote(?2), printf('%s|%d|%f', ?1, ?1, ?2);
select a.x, b.y from (select ? as x) a, (select ? as y) b;
with c(v) as (select ?1 union all select v + 1 from c where v < ?1 + 3) select v from c;
select * from t limit ? offset ?;
